#ifndef TIMER_H
#define TIMER_H

#include <chrono>
#include <cstdlib>
#include <string>

// Hierarchical wall-clock timer.  Constructing a Timer starts it; destruction
// records the elapsed time under `name` and adds it to its parent's
// child_time accumulator (so self-time = wall_time - sum_of_child_times).
//
// Uses an internal timer stack: each Timer pushes its name on construction and
// pops it on destruction, so a Timer created inside another Timer's scope is
// considered a child.
struct Timer {
    std::chrono::high_resolution_clock::time_point start;
    const char* name;
    Timer(const char* n);
    ~Timer();
};

// When SIMPLIFY_NO_TIMERS is set in the environment, TIMER(...) compiles down
// to a stack-local bool so the instrumented build has ~zero per-scope cost.
// Usage: SIMPLIFY_NO_TIMERS=1 ./build/simplify ...
inline bool timer_disabled() {
    static const bool disabled = std::getenv("SIMPLIFY_NO_TIMERS") != nullptr;
    return disabled;
}

// Convenience macro: declare a stack-local Timer that lives for the rest of
// the enclosing scope.
#define TIMER(name) \
    do { if (!::timer_disabled()) { static_cast<void>(0); } } while (0)
#define TIMER_REAL(name) Timer _timer_real(name)

// Print a hierarchical tree of all recorded timers, sorted by wall time
// per branch.  No-op if no timers have been recorded.
void print_timing_summary();

#endif // TIMER_H

