#ifndef TIMER_H
#define TIMER_H

#include <chrono>
#include <cstdlib>
#include <string>

// Hierarchical wall-clock timer.  Constructing a Timer starts it; destruction
// records the elapsed time under `name` and adds it to its parent's
// child_time accumulator (so self-time = wall_time - sum_of_child_times).
//
// Uses an internal timer stack: each Timer pushes its name on construction and
// pops it on destruction, so a Timer created inside another Timer's scope is
// considered a child.
struct Timer {
    std::chrono::high_resolution_clock::time_point start;
    const char* name;
    Timer(const char* n);
    ~Timer();
};

// When SIMPLIFY_NO_TIMERS is set in the environment, the TIMER() macro
// compiles to a no-op.  This lets us measure the *true* cost of instrumented
// code paths (no per-scope timer overhead) and compare against the
// instrumented build.  Usage:  SIMPLIFY_NO_TIMERS=1 ./build/simplify ...
inline bool timer_disabled() {
    static const bool disabled = []{
        const char* e = std::getenv("SIMPLIFY_NO_TIMERS");
        return e != nullptr && e[0] != '\0' && e[0] != '0';
    }();
    return disabled;
}

// Timer_dummy is an empty struct that costs nothing to construct/destroy.
// When timer_disabled() is true, we want TIMER() to declare a Timer_dummy
// instead of a real Timer.
//
// Macro strategy: always declare a `TimerHolder` whose lifetime spans the
// enclosing scope.  Its constructor decides whether to start a real timer or
// stay dormant.  This avoids the scoping issue of `if/else` declarations.
struct TimerHolder {
    Timer t;
    inline TimerHolder(const char* n)
        : t(timer_disabled() ? static_cast<const char*>(nullptr) : n) {}
};
#define TIMER(name) ::TimerHolder _timer_holder_##__LINE__(name)

// Print a hierarchical tree of all recorded timers, sorted by wall time
// per branch.  No-op if no timers have been recorded.
void print_timing_summary();

#endif // TIMER_H

