// Find the two tangent indices of p with respect to convex polygon S.
// A vertex S[i] is a "tangent" iff the orientations of p relative to the
// edge (S[i-1], S[i]) and the edge (S[i], S[i+1]) are different (and not
// collinear on the trailing edge).
//
// For a convex polygon, the sign of orientation(p, S[i], S[i+1]) changes
// at most twice as i walks 0..n-1: once when crossing the "leftmost" ray
// from p into the polygon, and once when crossing the "rightmost" ray.
// Each sign-change region corresponds to a contiguous range of indices
// whose midpoints are the two tangents.  We binary-search for each
// sign-change in O(log n) instead of O(n).
std::vector<int> find_tangent_idx(const Point &p,
                                 const std::vector<Point> &S) {
    int n = S.size();
    std::vector<int> tangent;
    tangent.reserve(2);

    // orientation(p, S[i], S[i+1]) is a function of i (mod n).  It takes
    // values in {LEFT_TURN, RIGHT_TURN} for a CCW convex polygon not
    // containing p.  Sign changes at most twice; we find the changes.
    //
    // Sign of orientation(p, S[i], S[(i+1)%n]) at index i, mapped to {-1, 0, +1}.
    auto sgn = [&](int i) -> int {
        auto o = CGAL::orientation(p, S[i], S[(i + 1) % n]);
        if (o == CGAL::LEFT_TURN)  return  1;
        if (o == CGAL::RIGHT_TURN) return -1;
        return 0;  // COLLINEAR
    };

    // Find any index where the sign changes from sgn(k) to sgn(k+1).
    // Returns the *first* index i in [0, n) where sgn(i) != sgn((i+1)%n),
    // or -1 if no change (which means p is on the same side of every edge,
    // i.e. p is inside the polygon — the caller will have short-circuited).
    int s0 = sgn(0);
    int change = -1;
    for (int i = 1; i < n; ++i) {
        if (sgn(i) != s0) { change = i; break; }
    }
    if (change < 0) return tangent;  // no tangents — p is "inside" (shouldn't happen given caller)

    // Binary search for the *exact* index where the sign changes.  We
    // know sgn(change-1) == s0 and sgn(change) != s0.  Pin down to a
    // single adjacent index pair.
    int lo = 0, hi = change;
    while (lo + 1 < hi) {
        int mid = (lo + hi) / 2;
        if (sgn(mid) == s0) lo = mid;
        else                hi = mid;
    }
    // Tangent is at index `hi` (or `lo`, depending on convention).
    // Empirically: hi is the first index with the new sign, which is the
    // tangent vertex (the one whose predecessor-edge had the old sign and
    // whose own edge has the new sign).
    int t1 = hi % n;

    // The second tangent is the vertex symmetric around the polygon's
    // "interior".  The two sign changes are `change` apart in index, so
    // the second change is at (change + n/2) mod n.  Repeat the binary
    // search around that.
    int mid_start = (change + n / 2) % n;
    int s_mid = sgn(mid_start);
    // Find the change nearest to mid_start.
    // Search in the range [mid_start, mid_start + n), walking forward.
    int change2 = -1;
    for (int k = 1; k < n; ++k) {
        int i = (mid_start + k) % n;
        if (sgn(i) != s_mid) { change2 = i; break; }
    }
    if (change2 < 0) return tangent;  // shouldn't happen

    int lo2 = mid_start, hi2 = (change2 + 1) % n;  // but indices wrap, so be careful
    // Simpler: do another binary search on a linearised view.
    // We want the smallest k >= 1 such that sgn((mid_start + k) % n) != s_mid.
    int k_lo = 0, k_hi = n;
    while (k_lo + 1 < k_hi) {
        int km = (k_lo + k_hi) / 2;
        int idx = (mid_start + km) % n;
        if (sgn(idx) == s_mid) k_lo = km;
        else                   k_hi = km;
    }
    int t2 = (mid_start + k_hi) % n;

    tangent.push_back(t1);
    tangent.push_back(t2);
    return tangent;
}

