// Find the two tangent indices of p with respect to convex polygon S.
// A vertex S[i] is a "tangent" iff orientation(p, S[i-1], S[i]) !=
// orientation(p, S[i], S[i+1]) (with the trailing edge non-collinear).
//
// For a convex polygon and external point p, the function
//   f(i) = orientation(p, S[i], S[i+1])
// takes values in {LEFT_TURN, RIGHT_TURN} (collinear is rare) and changes
// sign at most twice as i walks 0..n-1.  Each sign change corresponds to
// one tangent vertex.  We binary-search for both sign changes in O(log n)
// instead of O(n).
std::vector<int> find_tangent_idx(const Point &p,
                                 const std::vector<Point> &S) {
    int n = S.size();
    std::vector<int> tangent;
    if (n < 3) return tangent;

    // f(i): sign of orientation(p, S[i], S[(i+1)%n]) — the orientation of
    // the edge leaving S[i] as seen from p.
    auto f = [&](int i) -> int {
        auto o = CGAL::orientation(p, S[i], S[(i + 1) % n]);
        return (o == CGAL::LEFT_TURN) ? 1 : (o == CGAL::RIGHT_TURN) ? -1 : 0;
    };

    // Find any index where f changes sign — this is one tangent.
    int f0 = f(0);
    int change1 = -1;
    for (int i = 1; i < n; ++i) {
        if (f(i) != f0) { change1 = i; break; }
    }
    if (change1 < 0) return tangent;  // no sign changes — p is inside the polygon

    // Binary-search the first sign change: smallest i in [0, n) where f(i) != f0.
    // We know f(change1) != f0.
    {
        int lo = 0, hi = change1;
        while (lo + 1 < hi) {
            int mid = (lo + hi) / 2;
            if (f(mid) == f0) lo = mid;
            else               hi = mid;
        }
        // Tangent: the vertex whose outgoing edge is the FIRST one with the
        // new sign.  That's index `hi`.
        tangent.push_back(hi);
    }

    // The second tangent is "antipodal" — roughly n/2 indices past the
    // first.  The sign flips once more, somewhere in [change1, change1 + n).
    // We binary-search again starting from mid = (change1 + n/2) % n.
    int mid2 = (change1 + n / 2) % n;
    int f_mid = f(mid2);

    // Find the next sign change at distance >= 1 from mid2.  Since the
    // polygon is convex, exactly one more sign change exists in this range.
    // Walk f along the circle from mid2 to find the boundary of the
    // constant-sign arc starting at mid2.
    {
        // Linearised search in [0, n) for the smallest k >= 1 such that
        // f((mid2 + k) % n) != f_mid.  Binary search by k.
        int k_lo = 0, k_hi = n;
        while (k_lo + 1 < k_hi) {
            int km = (k_lo + k_hi) / 2;
            int idx = (mid2 + km) % n;
            if (f(idx) == f_mid) k_lo = km;
            else                  k_hi = km;
        }
        // Tangent 2: the vertex whose outgoing edge is the FIRST one with
        // the new sign past mid2.  That's (mid2 + k_hi) % n.
        tangent.push_back((mid2 + k_hi) % n);
    }
    return tangent;
}

