    // such that f((mid + k_lo) % n) == f_mid (no tangent yet); the
    // boundary is at k_lo + 1.
    int k_lo = 0;
    {
        int lo = 1, hi = n;
        // Invariant: f((mid + lo - 1) % n) == f_mid (no tangent yet at lo-1)
        //            f((mid + hi) % n) triggers tangent condition OR hi == n.
        // Initial: at k=0, f_mid itself is constant, so lo=1 starts at the
        // boundary where we haven't moved.
        while (lo < hi) {
            int km = (lo + hi) / 2;
            int prev_idx = (mid + km - 1) % n;
            int prev_f = (km == 1) ? f_mid : f(prev_idx);
            int idx = (mid + km) % n;
            int cur_f = f(idx);
            int tangent_here = (cur_f != 0 && cur_f != prev_f) ? 1 : 0;
            if (tangent_here) {
                hi = km;
            } else {
                lo = km + 1;
            }
        }
        k_lo = lo;
    }
    // The boundary is at k = k_lo.  Tangent vertex is at (mid + k_lo) % n.
    int t2 = (mid + k_lo) % n;
    tangent.push_back(t2);
    return tangent;
}

