// Test if every vertex of poly A is inside poly B.  Cheaper than
// running the full Sutherland-Hodgman clipper when A ⊆ B.
static bool all_vertices_inside(const std::vector<Point>& A, const std::vector<Point>& B) {
    for (const auto& p : A) {
        if (!point_in_convex_poly(p, B)) return false;
    }
    return true;
}

// Intersection of two convex polygons using Sutherland-Hodgman clipping.
// Both inputs must be CCW (we normalise them if not).
//
// Total work is O(|P| * |Q|) where each unit is one `orientation` test.
// For our typical inputs (|P|~12, |Q|~19) this is much cheaper than the
// O'Rourke state machine.
//
// Returns the intersection polygon in CCW order, or {} if empty.
static std::vector<Point> convex_intersect_fast(const std::vector<Point>& Pin,
                                                 const std::vector<Point>& Qin) {
    if (Pin.size() < 3 || Qin.size() < 3) return {};

    auto signed_area = [](const std::vector<Point>& P) {
        double s = 0;
        int sz = (int)P.size();
        for (int i = 0; i < sz; ++i) {
            const Point& a = P[i];
            const Point& b = P[(i + 1) % sz];
            s += CGAL::to_double(a.x() * b.y() - b.x() * a.y());
        }
        return s / 2;
    };

    // Normalise both to CCW.  Sutherland-Hodgman assumes the half-plane
    // is the LEFT of each directed edge; reversing a CW polygon flips
    // which side is "inside" and silently produces the wrong answer.
    std::vector<Point> P, Q;
    P.reserve(Pin.size());
    Q.reserve(Qin.size());
    if (signed_area(Pin) < 0) { P.assign(Pin.rbegin(), Pin.rend()); }
    else                       { P = Pin; }
    if (signed_area(Qin) < 0) { Q.assign(Qin.rbegin(), Qin.rend()); }
    else                       { Q = Qin; }

    // Containment shortcuts: only return the inner polygon when *every*
    // vertex of one polygon is inside the other.  Earlier we tested only
    // a single vertex (Pin[0] or Qin[0]), which is a correct test only if
    // the polygons are guaranteed to overlap fully — not the case here.
    // The single-vertex check fired incorrectly when F[0] was on Q's
    // boundary (a common case) but most of F was outside Q, causing the
    // algorithm to return F unchanged and lose the real intersection.
    if (all_vertices_inside(P, Q)) return Q;  // P ⊂ Q
    if (all_vertices_inside(Q, P)) return P;  // Q ⊂ P

    // Otherwise clip P against each edge of Q.
    std::vector<Point> running = P;
    int m = (int)Q.size();
    for (int i = 0; i < m; ++i) {
        const Point& a = Q[i];
        const Point& b = Q[(i + 1) % m];
        running = clip_halfplane(running, a, b);
        if (running.size() < 3) return {};
    }
    return running;
}

