// Intersection of two convex polygons using CGAL's exact-arithmetic
// Boolean set operations on general polygons.  This is the CGAL
// counterpart of `boost::geometry::intersection` and was effectively
// what the previous boost-based implementation used; it produces a
// correct convex-convex intersection polygon (with proper exact
// intersection points) without the numerical drift of a hand-rolled
// Sutherland-Hodgman clipper on inexact constructions.
static std::vector<Point> convex_intersect_fast(const std::vector<Point>& Pin,
                                                 const std::vector<Point>& Qin) {
    if (Pin.size() < 3 || Qin.size() < 3) return {};

    // Cheap containment shortcuts: if one polygon is entirely inside the
    // other, return the inner one (these are the common cases for tiny F
    // and slightly larger Gi, or vice versa).
    if (point_in_convex_poly(Pin[0], Qin)) return Pin;  // F ⊂ Gi
    if (point_in_convex_poly(Qin[0], Pin)) return Qin;  // Gi ⊂ F

    // Build CGAL polygons and let the kernel do the exact intersection.
    // `intersection` is the same name as the boolean-set-ops free function.
    Polygon P(Pin.begin(), Pin.end());
    Polygon Q(Qin.begin(), Qin.end());
    try {
        if (!P.is_simple() || !Q.is_simple()) return {};
    } catch (...) {
        return {};  // is_simple can throw on degenerate input
    }

    std::vector<Polygon_with_holes> output;
    try {
        CGAL::intersection(P, Q, std::back_inserter(output));
    } catch (...) {
        return {};  // degenerate inputs — give up
    }
    if (output.empty()) return {};

    // For convex ∩ convex there's exactly one result with no holes.
    // Pick the largest by area (defensive — should always be a single result).
    auto best = output.begin();
    for (auto it = output.begin(); it != output.end(); ++it) {
        if (it->has_holes()) continue;
        try {
            if (best->has_holes() ||
                CGAL::to_double(it->outer_boundary().area()) >
                CGAL::to_double(best->outer_boundary().area())) {
                best = it;
            }
        } catch (...) { continue; }
    }
    if (best->has_holes()) return {};  // shouldn't happen for convex ∩ convex

    const Polygon& inter = best->outer_boundary();
    std::vector<Point> result;
    result.reserve(inter.size());
    for (auto it = inter.vertices_begin(); it != inter.vertices_end(); ++it) {
        result.push_back(*it);
    }
    return result;
}

