// Compare boost::geometry::intersection output to my SH output for the test case
#include <boost/geometry.hpp>
#include <boost/geometry/geometries/point_xy.hpp>
#include <boost/geometry/geometries/polygon.hpp>
#include <iostream>
#include <iomanip>

namespace bg = boost::geometry;
typedef bg::model::d2::point_xy<double> BgPoint;
typedef bg::model::polygon<BgPoint, true, true> BgPolygon;

// My SH implementation (copied from simplify.cpp)
static double signed_area(const std::vector<std::pair<double,double>>& P) {
    double s = 0;
    int sz = (int)P.size();
    for (int i = 0; i < sz; ++i) {
        s += P[i].first * P[(i+1)%sz].second - P[(i+1)%sz].first * P[i].second;
    }
    return s / 2;
}

static double orient(double ax, double ay, double bx, double by, double px, double py) {
    return (bx-ax)*(py-ay) - (by-ay)*(px-ax);
}

static std::pair<double,double> line_intersect(double ax, double ay, double bx, double by,
                                                  double p1x, double p1y, double p2x, double p2y) {
    double A1 = by - ay, B1 = ax - bx, C1 = A1*ax + B1*ay;
    double A2 = p2y - p1y, B2 = p1x - p2x, C2 = A2*p1x + B2*p1y;
    double det = A1*B2 - A2*B1;
    return {(B2*C1 - B1*C2)/det, (A1*C2 - A2*C1)/det};
}

static std::vector<std::pair<double,double>> clip_halfplane(
    const std::vector<std::pair<double,double>>& subject,
    double ax, double ay, double bx, double by) {
    int n = (int)subject.size();
    if (n == 0) return {};
    std::vector<std::pair<double,double>> out;
    for (int i = 0; i < n; ++i) {
        auto [curx, cury] = subject[i];
        auto [prevx, prevy] = subject[(i+n-1)%n];
        double o_cur = orient(ax, ay, bx, by, curx, cury);
        double o_prev = orient(ax, ay, bx, by, prevx, prevy);
