        bool prev_in = o_prev >= 0;
        // Hmm — let me re-check: CGAL::orientation(a, b, p) returns RIGHT_TURN if
        // (b-a) x (p-a) < 0, i.e., (bx-ax)*(py-ay) - (by-ay)*(px-ax) < 0.
        // "inside" (left of directed edge a->b) is when (b-a) x (p-a) >= 0
