        if (cur_in) {
            if (!prev_in) {
                auto pt = line_intersect(ax, ay, bx, by, prevx, prevy, curx, cury);
                out.push_back(pt);
            }
            out.push_back({curx, cury});
        } else if (prev_in) {
            auto pt = line_intersect(ax, ay, bx, by, prevx, prevy, curx, cury);
            out.push_back(pt);
        }
