}

static std::vector<std::pair<double,double>> my_sh(
    const std::vector<std::pair<double,double>>& Pin,
    const std::vector<std::pair<double,double>>& Qin) {
    if (Pin.size() < 3 || Qin.size() < 3) return {};
    std::vector<std::pair<double,double>> P, Q;
    if (signed_area(Pin) < 0) P.assign(Pin.rbegin(), Pin.rend());
    else P = Pin;
    if (signed_area(Qin) < 0) Q.assign(Qin.rbegin(), Qin.rend());
