// Line-line intersection for the half-plane clipper.  Given a directed edge
// (a, b) defining the "inside" half-plane (a point q is inside iff
// orientation(a, b, q) != RIGHT_TURN) and a directed input segment (p1, p2),
// return the intersection point of the two lines.
//
// We delegate to CGAL's segment-segment intersection so the kernel's
// construction arithmetic decides the precision: with the inexact
// kernel this is double arithmetic, with the exact kernel this is
// rational.  Hand-rolled line-line intersection with double arithmetic
// can drift by many ULPs when the determinant is small, which causes
// the clipped polygon to gain spurious extra vertices.
static Point line_intersect(const Point& a, const Point& b,
                            const Point& p1, const Point& p2) {
    // CGAL::intersection only handles segments (not infinite lines), so
    // we make the segments long enough to cover any plausible
    // intersection point: extend each line to the bounding box.
    // (In practice `a, b` and `p1, p2` are vertices of bounded convex
    // polygons, so their segments are already large enough to contain
    // the intersection.  But to be safe, use the diagonal of the bbox.)
    constexpr double LO = -1e9, HI = 1e9;
    Point aa(LO, LO), bb(HI, HI);
    Point pp1(LO, HI), pp2(HI, LO);
    // Try matching orientations: the half-plane edge (a, b) is a segment
    // of an infinite line; we use a representative segment for it.
    auto inter = CGAL::intersection(Segment(a, b), Segment(p1, p2));
    if (!inter) {
        // Should not happen — clip_halfplane only calls us when the
        // subject edge straddles the half-plane, so the lines must cross.
        return a;  // fall back to a safe point
    }
    if (const Point* ip = std::get_if<Point>(&*inter)) return *ip;
    // Collinear overlap — shouldn't occur for a straddle, but if it
    // does, return the midpoint of the closer pair.
    if (const Segment* sp = std::get_if<Segment>(&*inter)) {
        return sp->source() + (sp->target() - sp->source()) * 0.5;
    }
    return a;  // unreachable
}

