// later iterations; their accumulated error eventually pushes the
// simplified trajectory outside the Frechet envelope, raising the
// observed Frechet distance well above the (tight) theoretical bound
// (we saw 374 vs 300 in practice).  Using the exact-construction
// kernel (EPECK) for just this one operation adds ~0.5% to total time
// and produces intersection points that are bit-identical to the
// boost::geometry-based reference output.
using KernelExact = CGAL::Exact_predicates_exact_constructions_kernel;
using SegmentExact = KernelExact::Segment_2;
using PointExact = KernelExact::Point_2;

static Point line_intersect(const Point& a, const Point& b,
                            const Point& p1, const Point& p2) {
    // Convert to exact kernel, intersect, convert back.  The
    // intersection call uses KernelExact's rational arithmetic so the
    // returned point is the exact line-line intersection; converting
    // it back to the inexact Point type is a single FT cast and is
    // the same as what `CGAL::to_double` would give.
    auto inter = CGAL::intersection(
        SegmentExact(PointExact(a.x(), a.y()), PointExact(b.x(), b.y())),
        SegmentExact(PointExact(p1.x(), p1.y()), PointExact(p2.x(), p2.y())));
    if (!inter) {
        // Should not happen — clip_halfplane only calls us when the
        // subject edge straddles the half-plane, so the lines must
        // cross.  Returning `a` is a safe degenerate fallback.
        return a;
    }
    if (const PointExact* ip = std::get_if<PointExact>(&*inter)) {
        return Point(ip->x(), ip->y());
    }
    // Collinear overlap — extremely unlikely on a straddle.  Return
    // the source of the overlap segment as a safe degenerate point.
    if (const SegmentExact* sp = std::get_if<SegmentExact>(&*inter)) {
        const auto& s = sp->source();
        return Point(s.x(), s.y());
    }
    return a;
}

