// Compare boost and my SH (with exact-kernel intersection) on the test case
#include <CGAL/Exact_predicates_inexact_constructions_kernel.h>
#include <CGAL/Exact_predicates_exact_constructions_kernel.h>
#include <CGAL/intersections.h>
#include <CGAL/Polygon_2.h>
#include <iostream>
#include <iomanip>

using Kernel = CGAL::Exact_predicates_inexact_constructions_kernel;
using Point = Kernel::Point_2;
using Segment = Kernel::Segment_2;

using KernelExact = CGAL::Exact_predicates_exact_constructions_kernel;
using SegmentExact = KernelExact::Segment_2;
using PointExact = KernelExact::Point_2;

static double orient(const Point& a, const Point& b, const Point& p) {
    return CGAL::to_double((b.x()-a.x())*(p.y()-a.y()) - (b.y()-a.y())*(p.x()-a.x()));
}

static Point line_intersect(const Point& a, const Point& b, const Point& p1, const Point& p2) {
    auto inter = CGAL::intersection(
        SegmentExact(PointExact(CGAL::to_double(a.x()), CGAL::to_double(a.y())),
                     PointExact(CGAL::to_double(b.x()), CGAL::to_double(b.y()))),
        SegmentExact(PointExact(CGAL::to_double(p1.x()), CGAL::to_double(p1.y())),
                     PointExact(CGAL::to_double(p2.x()), CGAL::to_double(p2.y()))));
    if (!inter) return a;
    if (const PointExact* ip = std::get_if<PointExact>(&*inter)) {
        return Point(CGAL::to_double(ip->x()), CGAL::to_double(ip->y()));
    }
    return a;
}

static std::vector<Point> clip_halfplane(const std::vector<Point>& subject,
                                          const Point& a, const Point& b) {
    int n = (int)subject.size();
    if (n == 0) return {};
    std::vector<Point> out;
    for (int i = 0; i < n; ++i) {
        const Point& cur = subject[i];
        const Point& prev = subject[(i + n - 1) % n];
        double o_cur = orient(a, b, cur);
        double o_prev = orient(a, b, prev);
        bool cur_in = o_cur >= 0;
        bool prev_in = o_prev >= 0;
        if (cur_in) {
            if (!prev_in) out.push_back(line_intersect(a, b, prev, cur));
            out.push_back(cur);
        } else if (prev_in) {
            out.push_back(line_intersect(a, b, prev, cur));
        }
    }
    return out;
}

