#ifndef TIMER_H
#define TIMER_H

#include <chrono>
#include <map>
#include <vector>
#include <cstdio>
#include <string>

extern std::map<std::string, double> g_timing;
extern std::map<std::string, long long> g_counters;
extern std::map<std::string, double> g_child_time;
extern std::vector<const char*> g_timer_stack;
extern std::map<std::string, std::vector<std::string>> g_children;

struct Timer {
    std::chrono::high_resolution_clock::time_point start;
    const char* name;
    Timer(const char* n) : name(n) {
        start = std::chrono::high_resolution_clock::now();
        g_timer_stack.push_back(name);
    }
    ~Timer() {
        auto end = std::chrono::high_resolution_clock::now();
        auto dur = std::chrono::duration<double, std::milli>(end - start).count();
        g_timing[name] += dur;
        g_counters[name]++;
        if (g_timer_stack.size() >= 2) {
            const char* parent = g_timer_stack[g_timer_stack.size() - 2];
            g_child_time[parent] += dur;
            g_children[parent].push_back(name);
        }
        g_timer_stack.pop_back();
    }
};

#define TIMER(name) Timer _timer(name)

inline void print_timing_report() {
    if (g_timing.empty()) return;
    fprintf(stderr, "\n========== TIMING SUMMARY ==========\n");
    fprintf(stderr, "%-40s %12s %12s %10s %7s\n", "Operation", "Wall (ms)", "Self (ms)", "Calls", "% Total");
    fprintf(stderr, "----------------------------------------------------------------------------------------\n");

    auto report_one = [&](const std::string& name, int depth) {
        auto it = g_timing.find(name);
        if (it == g_timing.end()) return;
        double wall = it->second;
        long long calls = g_counters[name];
        double self = wall - g_child_time[name];
        double pct = (g_timing.count("total") ? wall / g_timing["total"] * 100.0 : 0.0);
        std::string indent(depth * 2, ' ');
        fprintf(stderr, "%s%-38s %12.2f %12.2f %10lld %6.1f%%\n",
                indent.c_str(), name.c_str(), wall, self, calls, pct);
    };

    report_one("total", 0);
    for (const auto& kv : g_timing) {
        if (kv.first == "total") continue;
        if (g_children.count(kv.first)) {
            report_one(kv.first, 1);
            for (const auto& child : g_children[kv.first]) {
                if (g_timing.count(child) && !g_children.count(child)) {
                    report_one(child, 2);
                }
            }
        }
    }
    fprintf(stderr, "----------------------------------------------------------------------------------------\n");
    if (g_timing.count("total")) {
        fprintf(stderr, "%-40s %12.2f\n", "TOTAL (wall time)", g_timing["total"]);
    }
    fprintf(stderr, "====================================\n");
}

#endif // TIMER_H

#ifndef TIMER_H
#define TIMER_H

#include <chrono>
#include <map>
#include <vector>
#include <string>
#include <cstdio>

namespace timer_detail {
    inline std::map<std::string, double>& timing() {
        static std::map<std::string, double> t;
        return t;
    }
    inline std::map<std::string, long long>& counters() {
        static std::map<std::string, long long> c;
        return c;
    }
    inline std::map<std::string, double>& child_time() {
        static std::map<std::string, double> c;
        return c;
    }
    inline std::map<std::string, std::vector<std::string>>& children() {
        static std::map<std::string, std::vector<std::string>> ch;
        return ch;
    }
    inline std::vector<const char*>& stack() {
        static std::vector<const char*> s;
        return s;
    }
}

struct Timer {
    std::chrono::high_resolution_clock::time_point start;
    const char* name;
    Timer(const char* n) : name(n) {
        start = std::chrono::high_resolution_clock::now();
        timer_detail::stack().push_back(name);
    }
    ~Timer() {
        auto end = std::chrono::high_resolution_clock::now();
        auto dur = std::chrono::duration<double, std::milli>(end - start).count();
        timer_detail::timing()[name] += dur;
        timer_detail::counters()[name]++;
        auto& stack = timer_detail::stack();
        if (stack.size() >= 2) {
            const char* parent = stack[stack.size() - 2];
            timer_detail::child_time()[parent] += dur;
            timer_detail::children()[parent].push_back(name);
        }
        stack.pop_back();
    }
};

#define TIMER(name) Timer _timer(name)

inline void print_timing_report() {
    auto& t = timer_detail::timing();
    if (t.empty()) return;
    fprintf(stderr, "\n========== TIMING SUMMARY ==========\n");
    fprintf(stderr, "%-40s %12s %12s %10s %7s\n", "Operation", "Wall (ms)", "Self (ms)", "Calls", "% Total");
    fprintf(stderr, "----------------------------------------------------------------------------------------\n");

