        long long calls = timer_detail::counters()[name];
        double self = wall - timer_detail::child_time()[name];
        double pct = (t.count("total") ? wall / t["total"] * 100.0 : 0.0);
        std::string indent(depth * 2, ' ');
        fprintf(stderr, "%s%-38s %12.2f %12.2f %10lld %6.1f%%\n",
                indent.c_str(), name.c_str(), wall, self, calls, pct);
    };

    report_one("total", 0);
    for (const auto& kv : t) {
        if (kv.first == "total") continue;
        if (timer_detail::children().count(kv.first)) {
            report_one(kv.first, 1);
            for (const auto& child : timer_detail::children()[kv.first]) {
                if (t.count(child) && !timer_detail::children().count(child)) {
                    report_one(child, 2);
                }
            }
        }
    }
    fprintf(stderr, "----------------------------------------------------------------------------------------\n");
    if (t.count("total")) {
        fprintf(stderr, "%-40s %12.2f\n", "TOTAL (wall time)", t["total"]);
    }
    fprintf(stderr, "====================================\n");
}

