    auto finish = [&](bool closed) {
        if (closed && !first_point) out.push_back(p0);
    };

    do {
        int a1 = (a + n - 1) % n;
        int b1 = (b + m - 1) % m;

        // Edge vectors A, B.  Kernel provides Vector_2 for point - point.
        Vector A = Pr[a] - Pr[a1];
        Vector B = Qr[b] - Qr[b1];

        int cross, aHB, bHA;
        char code;
        Point p, q;
        {
            TIMER("sgn_tests");
            cross = area_sign_vec(A, B);
            aHB   = area_sign(Qr[b1], Qr[b], Pr[a]);
            bHA   = area_sign(Pr[a1], Pr[a], Qr[b]);
            code  = seg_seg_int(Pr[a1], Pr[a], Qr[b1], Qr[b], p, q);
        }
        {
            TIMER("main_loop_body");
            if (code == '1' || code == 'v') {
                if (inflag == InFlag::Unknown && first_point) {
                    aa = ba = 0;
                    first_point = false;
                    p0 = p;
                }
                out.push_back(p);
                inflag = in_out(p, inflag, aHB, bHA);
            }

            // Special case: A & B overlap and oppositely oriented -> shared edge
            if ((code == 'e') && (dot_sign(Pr[a1], Pr[a], Qr[b1], Qr[b]) < 0)) {
                shared_edge = true;
                shared_p = p;
                shared_q = q;
                break;  // leave the do-loop; post-process below handles it
            }

            // Special case: A & B collinear -> advance without printing
            if ((cross == 0) && (aHB == 0) && (bHA == 0)) {
                if (inflag == InFlag::Pin)
                    b = advance(b, ba, m, inflag == InFlag::Qin, Qr[b], out);
                else
                    a = advance(a, aa, n, inflag == InFlag::Pin, Pr[a], out);
            } else if (cross >= 0) {                if (bHA > 0)
                    a = advance(a, aa, n, inflag == InFlag::Pin, Pr[a], out);
                else
                    b = advance(b, ba, m, inflag == InFlag::Qin, Qr[b], out);
            } else {  // cross < 0
                if (aHB > 0)
                    b = advance(b, ba, m, inflag == InFlag::Qin, Qr[b], out);
                else
                    a = advance(a, aa, n, inflag == InFlag::Pin, Pr[a], out);
            }
        }
    } while (((aa < n) || (ba < m)) && (aa < 2 * n) && (ba < 2 * m));

    if (shared_edge) {
        out.push_back(shared_p);
        out.push_back(shared_q);
    } else {
        finish(!first_point);
    }

    if (inflag == InFlag::Unknown && first_point) {
        // Boundaries do not cross: P is inside Q, or Q is inside P, or they
        // touch at a single point.  Detect containment by sampling one
        // vertex of P.  (The Pin_n/Qin_n winding normalization above
        // means we can use the strict CCW point-in-convex-poly test.)
        {
            TIMER("containment");
            if (point_in_convex_poly(Pr[0], Qr)) return Pr;
            if (point_in_convex_poly(Qr[0], Pr)) return Qr;
        }
        return {};
    }

    // Post-process: the main loop may emit collinear "kink" vertices
    // where one polygon's vertex lies on the other polygon's edge.
    // These are valid intersections but are not on the convex hull of
    // the output, so we run a final convex-hull pass to remove them.
    if (out.size() >= 3) {
        std::vector<Point> hull;
        hull.reserve(out.size());
        {
            TIMER("post_hull");
            CGAL::convex_hull_2(out.begin(), out.end(), std::back_inserter(hull));
        }
        return hull;
    }
    return out;
}

content.text:
`Epick` is the CGAL kernel with exact predicates but inexact (double) constructions. It's much faster than `Epeck` (which uses exact rationals for constructions).

To switch, change one line in `simplify_geometry.h`:

```cpp
// Epeck (current - exact constructions, slow):
using Kernel = CGAL::Exact_predicates_exact_constructions_kernel;

// Epick (faster - exact predicates only, constructions are doubles):
using Kernel = CGAL::Exact_predicates_inexact_constructions_kernel;
```

Then rebuild. Let me do it and test:

