report_one("total", 0);
for (const auto& kv : t) {
    if (kv.first == "total") continue;
    if (timer_detail::children().count(kv.first)) {
        report_one(kv.first, 1);
        // Print each unique child only once (children() accumulates
        // every parent->child invocation; printing per-invocation
        // would explode the report when a parent is called 10k+ times).
        std::set<std::string> printed;
        for (const auto& child : timer_detail::children()[kv.first]) {
            if (printed.insert(child).second &&
                t.count(child) &&
                !timer_detail::children().count(child)) {
                report_one(child, 2);
            }
        }
    }
}

