static void intersect(const Polygon& subject, const Polygon& clip,
                        std::back_insert_iterator<std::vector<Polygon_with_holes>> result) {
    std::vector<Point> P_verts, Q_verts;
    {
        TIMER("copy_verts");
        P_verts.reserve(subject.size());
        Q_verts.reserve(clip.size());
        for (auto it = subject.vertices_begin(); it != subject.vertices_end(); ++it) {
            P_verts.push_back(*it);
        }
        for (auto it = clip.vertices_begin(); it != clip_vertices_end(); ++it) {
            Q_verts.push_back(*it);
        }
    }

    std::vector<Point> verts;
    {
        TIMER("convex_intersect");
        verts = orourke_cgal::convex_intersect(P_verts, Q_verts);
    }
    if (verts.empty()) return;

    // The intersection should be convex, hence simple.  But the O'Rourke
    // main loop can emit kinks / collinear / duplicate vertices that
    // confuse CGAL's is_simple_2 check.  Walk the list and drop any vertex
    // that is collinear with (or coincides with) its predecessor — for a
    // convex polygon, that strictly tightens the chain without changing
    // the underlying region.  Loop until a pass makes no change so that
    // a chain like A-B-C-D where B and C are both collinear with A-D
    // collapses to just A-D in one pass.
    bool changed = true;
    while (changed && verts.size() >= 3) {
        changed = false;
        std::vector<Point> cleaned;
        cleaned.reserve(verts.size());
        const int n = (int)verts.size();
        for (int i = 0; i < n; ++i) {
            const Point& prev = cleaned.empty() ? verts[(i - 1 + n) % n]
                                                : cleaned.back();
            const Point& cur  = verts[i];
            const Point& next = verts[(i + 1) % n];
            if (cur == prev || cur == next) { changed = true; continue; }
            if (!cleaned.empty()) {
                auto o = CGAL::orientation(prev, cur, next);
                if (o == CGAL::COLLINEAR) { changed = true; continue; }
            }
            cleaned.push_back(cur);
        }
        if ((int)cleaned.size() != n) verts.swap(cleaned);
        else break;
    }
    if (verts.size() < 3) return;

    Polygon inter_poly(verts.begin(), verts.end());
    if (!inter_poly.is_simple()) return;
    if (inter_poly.is_clockwise_oriented()) inter_poly.reverse_orientation();
    *result++ = Polygon_with_holes(inter_poly);
}

