std::vector<Point> simplify(const std::vector<Point> &stream, MultiViewer* viewer = nullptr) {
    TIMER("simplify");
    std::vector<Point> simplified;
    std::cout << "Simplifying...\n";
    int cur = 0;
    while (cur != int(stream.size())) {
        const std::size_t before = simplified.size();
        cur = get_longest_stab(stream, cur, simplified, viewer);
        // get_longest_stab always appends two points (segment start and
        // end).  If a segment only consumed its starting point, the two
        // are equal and we drop the duplicate.  We also drop the
        // duplicate at segment boundaries: the previous call's endpoint
        // (last_pi of the prior segment) coincides with this call's p0,
        // so the second point of the previous segment is the same as the
        // first point of this segment.  Removing that keeps the
        // simplified stream strictly shorter than 2 * (number of
        // segments) without losing any information.
        while (simplified.size() >= 2 &&
               simplified[simplified.size() - 1] == simplified[simplified.size() - 2]) {
            simplified.pop_back();
