#include "simplify_geometry.h"
#include <boost/geometry.hpp>
#include <boost/geometry/geometries/point_xy.hpp>
#include <boost/geometry/geometries/polygon.hpp>
#include <iostream>
#include <fstream>
#include <vector>
#include <cmath>
#include <algorithm>

using BgPoint = boost::geometry::model::d2::point_xy<double>;
using BgPolygon = boost::geometry::model::polygon<BgPoint, true, true>;

static BgPolygon to_bg_polygon(const std::vector<Point>& points) {
    BgPolygon polygon;
    auto& outer = polygon.outer();
    outer.reserve(points.size() + 1);
    for (const auto& point : points) {
        outer.emplace_back(CGAL::to_double(point.x()), CGAL::to_double(point.y()));
    }
    if (!points.empty()) {
        outer.emplace_back(CGAL::to_double(points.front().x()), CGAL::to_double(points.front().y()));
    }
    boost::geometry::correct(polygon);
    return polygon;
}

static std::vector<Point> from_bg_polygon(const BgPolygon& polygon) {
    std::vector<Point> points;
    const auto& outer = polygon.outer();
    if (outer.size() <= 1) return points;
    points.reserve(outer.size() - 1);
    for (std::size_t i = 0; i + 1 < outer.size(); ++i) {
        points.emplace_back(outer[i].x(), outer[i].y());
    }
    return points;
}

// O'Rourke from simplify.cpp
namespace orourke_cgal {
enum class InFlag { Pin, Qin, Unknown };
static int area_sign(const Point& a, const Point& b, const Point& c) {
    switch (CGAL::orientation(a, b, c)) {
        case CGAL::LEFT_TURN:  return  1;
        case CGAL::RIGHT_TURN: return -1;
        case CGAL::COLLINEAR:  return  0;
    }
    return 0;
}
static int area_sign_vec(const Vector& a, const Vector& b) {
    auto c = CGAL::determinant(a, b);
    if (c > 0) return  1;
    if (c < 0) return -1;
    return 0;
}
static bool between(const Point& a, const Point& b, const Point& c) {
    if (CGAL::orientation(a, b, c) != CGAL::COLLINEAR) return false;
    if (CGAL::abs(b.x() - a.x()) >= CGAL::abs(b.y() - a.y())) {
        return (a.x() <= c.x() && c.x() <= b.x()) ||
               (a.x() >= c.x() && c.x() >= b.x());
    }
    return (a.y() <= c.y() && c.y() <= b.y()) ||
           (a.y() >= c.y() && c.y() >= b.y());
}
static int dot_sign(const Point& a, const Point& b,
                    const Point& c, const Point& d) {
    auto ux = b.x() - a.x(), uy = b.y() - a.y();
    auto vx = d.x() - c.x(), vy = d.y() - c.y();
    auto s  = ux * vx + uy * vy;
    if (s > 0) return  1;
    if (s < 0) return -1;
    return 0;
}
static char seg_seg_int(const Point& a, const Point& b,
                        const Point& c, const Point& d,
                        Point& out_p, Point& out_q) {
    auto inter = CGAL::intersection(Segment(a, b), Segment(c, d));
    if (!inter) return '0';
    if (const Point* ip = std::get_if<Point>(&*inter)) {
        bool on_a = CGAL::squared_distance(*ip, a) == 0 ||
                    CGAL::squared_distance(*ip, b) == 0;
        bool on_c = CGAL::squared_distance(*ip, c) == 0 ||
                    CGAL::squared_distance(*ip, d) == 0;
        out_p = *ip;
        return (on_a || on_c) ? 'v' : '1';
    }
    if (const Segment* seg = std::get_if<Segment>(&*inter)) {
        out_p = seg->source();
        out_q = seg->target();
        return 'e';
    }
    return '0';
}
static int advance(int a, int& aa, int n, bool inside,
                   const Point& v, std::vector<Point>& out) {
    if (inside) out.push_back(v);
    aa++;
    return (a + 1) % n;
}
static InFlag in_out(const Point& /*p*/, InFlag inflag, int aHB, int bHA) {
    if      (aHB > 0) return InFlag::Pin;
    else if (bHA > 0) return InFlag::Qin;
    return inflag;
}
static bool point_in_convex_poly(const Point& p, const std::vector<Point>& poly) {
    int n = (int)poly.size();
    for (int i = 0; i < n; ++i) {
        const Point& a = poly[i];
        const Point& b = poly[(i + 1) % n];
        if (CGAL::orientation(a, b, p) == CGAL::RIGHT_TURN) return false;
    }
    return true;
}
static bool is_ccw(const std::vector<Point>& P) {
    double s = 0;
    int sz = (int)P.size();
    for (int i = 0; i < sz; ++i) {
        const Point& a = P[i];
        const Point& b = P[(i + 1) % sz];
        s += CGAL::to_double(a.x() * b.y() - b.x() * a.y());
    }
    return s > 0;
}
static std::vector<Point> convex_intersect(const std::vector<Point>& Pin,
                                           const std::vector<Point>& Qin) {
    int n = (int)Pin.size();
    int m = (int)Qin.size();
    if (n < 3 || m < 3) return {};
    std::vector<Point> Pr = Pin, Qr = Qin;
    if (!is_ccw(Pr)) std::reverse(Pr.begin(), Pr.end());
    if (!is_ccw(Qr)) std::reverse(Qr.begin(), Qr.end());
    auto leftmost_index = [](const std::vector<Point>& P) {
        int best = 0;
        for (int i = 1; i < (int)P.size(); ++i) {
            if (CGAL::compare_y(P[i], P[best]) == CGAL::SMALLER ||
                (CGAL::compare_y(P[i], P[best]) == CGAL::EQUAL &&
                 CGAL::compare_x(P[i], P[best]) == CGAL::SMALLER)) {
                best = i;
            }
        }
        return best;
    };
    int a = leftmost_index(Pr);
    int b = leftmost_index(Qr);
    int aa = 0, ba = 0;
    InFlag inflag = InFlag::Unknown;
    bool first_point = true;
    Point p0;
    std::vector<Point> out;
    do {
        int a1 = (a + n - 1) % n;
        int b1 = (b + m - 1) % m;
        Vector A = Pr[a] - Pr[a1];
        Vector B = Qr[b] - Qr[b1];
        int cross  = area_sign_vec(A, B);
        int aHB    = area_sign(Qr[b1], Qr[b], Pr[a]);
        int bHA    = area_sign(Pr[a1], Pr[a], Qr[b]);
        Point p, q;
        char code = seg_seg_int(Pr[a1], Pr[a], Qr[b1], Qr[b], p, q);
        if (code == '1' || code == 'v') {
            if (inflag == InFlag::Unknown && first_point) {
                aa = ba = 0;
                first_point = false;
                p0 = p;
            }
            out.push_back(p);
            inflag = in_out(p, inflag, aHB, bHA);
        }
        if ((code == 'e') && (dot_sign(Pr[a1], Pr[a], Qr[b1], Qr[b]) < 0)) {
            out.push_back(p);
            out.push_back(q);
            return out;
        }
        if ((cross == 0) && (aHB < 0) && (bHA < 0)) {
            return {};
        }
        if ((cross == 0) && (aHB == 0) && (bHA == 0)) {
            if (inflag == InFlag::Pin)
                b = advance(b, ba, m, inflag == InFlag::Qin, Qr[b], out);
            else
                a = advance(a, aa, n, inflag == InFlag::Pin, Pr[a], out);
        } else if (cross >= 0) {
            if (bHA > 0)
                a = advance(a, aa, n, inflag == InFlag::Pin, Pr[a], out);
            else
                b = advance(b, ba, m, inflag == InFlag::Qin, Qr[b], out);
        } else {
            if (aHB > 0)
                b = advance(b, ba, m, inflag == InFlag::Qin, Qr[b], out);
            else
                a = advance(a, aa, n, inflag == InFlag::Pin, Pr[a], out);
        }
    } while (((aa < n) || (ba < m)) && (aa < 2 * n) && (ba < 2 * m));
    if (first_point) {
        if (point_in_convex_poly(Pr[0], Qr)) return Pr;
        if (point_in_convex_poly(Qr[0], Pr)) return Qr;
        return {};
    }
    out.push_back(p0);
    return out;
}
} // namespace

static void print_pts(const std::vector<Point>& pts, const char* label) {
    std::cout << label << " (" << pts.size() << " pts):\n";
    for (const auto& p : pts) {
        std::cout << "  (" << CGAL::to_double(p.x()) << "," << CGAL::to_double(p.y()) << ")\n";
    }
    std::cout << "\n";
}

int main() {
    std::ifstream fin("data/taxi/1.txt");
    if (!fin) { std::cerr << "Cannot open data/taxi/1.txt\n"; return 1; }
    int N; fin >> N;
    std::vector<Point> stream(N);
    for (int i = 0; i < N; ++i) {
        double x, y; fin >> x >> y;
        stream[i] = Point(x, y);
    }

    Point p0 = stream[0];
    Point p3 = stream[3];
    double px0 = CGAL::to_double(p0.x()), py0 = CGAL::to_double(p0.y());
    double px3 = CGAL::to_double(p3.x()), py3 = CGAL::to_double(p3.y());
    double EPSILON = 0.6, DELTA = 200;
    double GRID = EPSILON * DELTA / (2 * 1.41421356237);
    double R = (1.0 + EPSILON / 2.0) * DELTA;
    double R2 = R * R;
    int y_min = -(R / GRID) - 1, y_max = -y_min;

    // Build P (grid points around p0)
    std::vector<Point> Ppts;
    for (int y = y_min; y <= y_max; y++) {
        double y_actual = y * GRID;
        int x_min = -std::sqrt(R2 - y_actual * y_actual) / GRID - 1;
        int x_max = -x_min;
        for (int x = x_min; x <= x_max; x++) {
            Ppts.emplace_back(px0 + x * GRID, py0 + y_actual);
        }
    }

    // Convex hull around p3
    std::vector<Point> boundaries;
    for (int y = y_min; y <= y_max; y++) {
        double y_actual = y * GRID;
        int x_min = -std::sqrt(R2 - y_actual * y_actual) / GRID - 1;
        boundaries.emplace_back(px3 + x_min * GRID, py3 + y_actual);
    }
    for (int y = y_min; y <= y_max; y++) {
        double y_actual = y * GRID;
        int x_max = (std::sqrt(R2 - y_actual * y_actual) / GRID) + 1;
        if (x_max != 0) boundaries.emplace_back(px3 + x_max * GRID, py3 + y_actual);
    }
    std::vector<Point> Qpts;
    CGAL::convex_hull_2(boundaries.begin(), boundaries.end(), std::back_inserter(Qpts));

    print_pts(Ppts, "P (grid pts)");
    print_pts(Qpts, "Q (convex hull)");

    std::cout << "=== TEST: F (Ppts) vs G_i (Qpts) ===\n";

    // O'Rourke
    std::vector<Point> our = orourke_cgal::convex_intersect(Ppts, Qpts);
    print_pts(our, "O'Rourke result");

    // Boost.Geometry
    BgPolygon lhs_polygon = to_bg_polygon(Ppts);
    BgPolygon rhs_polygon = to_bg_polygon(Qpts);
    std::vector<BgPolygon> output;
    boost::geometry::intersection(lhs_polygon, rhs_polygon, output);
    if (!output.empty()) {
        auto best = std::max_element(output.begin(), output.end(),
            [](const BgPolygon& a, const BgPolygon& b) {
                return boost::geometry::area(a) < boost::geometry::area(b);
            });
        std::vector<Point> bg_pts = from_bg_polygon(*best);
        print_pts(bg_pts, "Boost.Geometry result");
    } else {
        std::cout << "Boost.Geometry: empty\n\n";
    }

    return 0;
}

