// Post-process O'Rourke output: remove duplicate and collinear vertices
// so CGAL's is_simple_2 check and Polygon constructor succeed.
static std::vector<Point> clean_convex_output(std::vector<Point> verts) {
    if (verts.size() < 3) return {};
    bool changed = true;
    while (changed && verts.size() >= 3) {
        changed = false;
        std::vector<Point> cleaned;
        cleaned.reserve(verts.size());
        const int n = (int)verts.size();
        for (int i = 0; i < n; ++i) {
            const Point& cur  = verts[i];
            const Point& next = verts[(i + 1) % n];
            const Point& prev = cleaned.empty() ? verts[(i - 1 + n) % n]
                                                : cleaned.back();
            if (cur == prev || cur == next) { changed = true; continue; }
            if (!cleaned.empty()) {
                if (CGAL::orientation(prev, cur, next) == CGAL::COLLINEAR) {
                    changed = true;
                    continue;
                }
            }
            cleaned.push_back(cur);
        }
        if ((int)cleaned.size() != n) verts.swap(cleaned);
        else break;
    }
    return verts;
}

