static std::vector<Point> intersect_convex_polygons(const std::vector<Point>& lhs,
                                                    const std::vector<Point>& rhs) {
    TIMER("convex_intersect");
    std::vector<Point> verts = orourke_cgal::convex_intersect(lhs, rhs);
    if (verts.empty()) return {};
    verts = clean_convex_output(std::move(verts));
    if (verts.size() < 3) return {};
    Polygon inter_poly(verts.begin(), verts.end());
    if (!inter_poly.is_simple()) return {};
    if (inter_poly.is_clockwise_oriented()) inter_poly.reverse_orientation();
    return verts;
}

