#include <iostream>
#include <vector>
#include "simplify_geometry.h"
#include <CGAL/Boolean_set_operations_2.h>

int main() {
    // The failing polygon from the log: F.size=10
    std::vector<Point> F = {
        Point(-1241.32, 4328.45),
        Point(-1198.9, 4243.6),
        Point(-1114.04, 4158.75),
        Point(-944.337, 4073.89),
        Point(-774.632, 4158.75),
        Point(-689.779, 4243.6),
        Point(-647.352, 4328.45),
        Point(552.901, 10000),
        Point(-2633.33, 10000)
    };

    // A typical Gi polygon
    std::vector<Point> Gi = {
        Point(-10000, -10000),
        Point(10000, -10000),
        Point(10000, 10000),
        Point(-10000, 10000)
    };

    std::cout << "Creating F polygon..." << std::endl;
    Polygon F_poly(F.begin(), F.end());
    std::cout << "F simple: " << F_poly.is_simple() << std::endl;
    std::cout << "F ccw: " << F_poly.is_counterclockwise_oriented() << std::endl;
    std::cout << "F size: " << F_poly.size() << std::endl;

    std::cout << "Creating Gi polygon..." << std::endl;
    Polygon Gi_poly(Gi.begin(), Gi.end());
    std::cout << "Gi simple: " << Gi_poly.is_simple() << std::endl;

    std::cout << "Calling CGAL::intersection..." << std::endl;
    std::vector<Polygon_with_holes> result;
    CGAL::intersection(F_poly, Gi_poly, std::back_inserter(result));
    std::cout << "Result size: " << result.size() << std::endl;

    if (!result.empty()) {
        const Polygon& outer = result[0].outer_boundary();
        std::cout << "Output polygon size: " << outer.size() << std::endl;
    }

    std::cout << "Done!" << std::endl;
    return 0;
}

