static std::vector<Point> intersect_convex_polygons(const std::vector<Point>& lhs,
                                                    const std::vector<Point>& rhs) {
    TIMER("convex_intersect");
    if (lhs.size() < 3 || rhs.size() < 3) return {};
    try {
        Polygon lhs_poly(lhs.begin(), lhs.end());
        Polygon rhs_poly(rhs.begin(), rhs.end());
        std::vector<Polygon_with_holes> result;
        CGAL::intersection(lhs_poly, rhs_poly, std::back_inserter(result));
        if (result.empty()) return {};
        const Polygon_with_holes& pwh = result[0];
        const Polygon& outer = pwh.outer_boundary();
        if (outer.size() < 3) return {};
        std::vector<Point> out(outer.container().begin(), outer.container().end());
        if (out.size() < 3) return {};
        return out;
    } catch (...) {
        return {};
    }
}

